mapper.select:
select p.id as id, p.is_active as is_active, p.address as address, p.description as description, p.is_available as is_available, p.property_type as property_type, p.rent_price as rent_price, p.room_count as room_count, p.title as roomTitle, u.full_name as ownerName, p.owner_id as ownerId, pa.amenity as amenity_amenities, pi.id as imageId, pi.image_url as image_url from property p left join property_amenities pa on p.id = pa.property_id left join users u on p.owner_id = u.id left join property_image pi on p.id = pi.property_id
p.is_available = true
AND p.property_type = #{propertyType}
AND p.address ILIKE CONCAT('%', #{address}, '%')
AND p.rent_price <= #{priceRange}
